1	// Compile-time layout lock for hybrid_state_v1. The ABI is a wire contract,
2	// so any offset or size drift must break every consumer at compile time.
3	
4	#ifndef HYBRID_STATE_ABI_CHECK_H
5	#define HYBRID_STATE_ABI_CHECK_H
6	
7	#include "hybrid/state_abi.h"
8	
9	// C++20 has static_assert; C11+ has _Static_assert. Pick the one that exists.
10	#ifndef __cplusplus
11	#  define static_assert _Static_assert
12	#endif
13	
14	static_assert(offsetof(struct hybrid_state_v1, magic)    == 0,    "magic@0");
15	static_assert(offsetof(struct hybrid_state_v1, version)  == 4,    "version@4");
16	static_assert(offsetof(struct hybrid_state_v1, flags)    == 8,    "flags@8");
17	static_assert(offsetof(struct hybrid_state_v1, hart_id)  == 12,   "hart_id@12");
18	static_assert(offsetof(struct hybrid_state_v1, pc)       == 16,   "pc@16");
19	static_assert(offsetof(struct hybrid_state_v1, priv)     == 24,   "priv@24");
20	
21	static_assert(offsetof(struct hybrid_state_v1, gpr)      == 32,   "gpr@32");
22	static_assert(offsetof(struct hybrid_state_v1, fpr)      == 288,  "fpr@288");
23	
24	static_assert(offsetof(struct hybrid_state_v1, mstatus)  == 544,  "mstatus@544");
25	static_assert(offsetof(struct hybrid_state_v1, mepc)     == 552,  "mepc@552");
26	static_assert(offsetof(struct hybrid_state_v1, mtvec)    == 560,  "mtvec@560");
27	static_assert(offsetof(struct hybrid_state_v1, mcause)   == 568,  "mcause@568");
28	static_assert(offsetof(struct hybrid_state_v1, mtval)    == 576,  "mtval@576");
29	static_assert(offsetof(struct hybrid_state_v1, mscratch) == 584,  "mscratch@584");
30	static_assert(offsetof(struct hybrid_state_v1, medeleg)  == 592,  "medeleg@592");
31	static_assert(offsetof(struct hybrid_state_v1, mideleg)  == 600,  "mideleg@600");
32	static_assert(offsetof(struct hybrid_state_v1, mip)      == 608,  "mip@608");
33	static_assert(offsetof(struct hybrid_state_v1, mie)      == 616,  "mie@616");
34	static_assert(offsetof(struct hybrid_state_v1, mcycle)   == 624,  "mcycle@624");
35	static_assert(offsetof(struct hybrid_state_v1, minstret) == 632,  "minstret@632");
36	static_assert(offsetof(struct hybrid_state_v1, satp)     == 640,  "satp@640");
37	
38	static_assert(offsetof(struct hybrid_state_v1, pmpcfg)   == 648,  "pmpcfg@648");
39	static_assert(offsetof(struct hybrid_state_v1, pmpaddr)  == 776,  "pmpaddr@776");
40	
41	static_assert(offsetof(struct hybrid_state_v1, vstart)   == 1288, "vstart@1288");
42	static_assert(offsetof(struct hybrid_state_v1, vtype)    == 1296, "vtype@1296");
43	static_assert(offsetof(struct hybrid_state_v1, vl)       == 1304, "vl@1304");
44	static_assert(offsetof(struct hybrid_state_v1, vlenb)    == 1312, "vlenb@1312");
45	static_assert(offsetof(struct hybrid_state_v1, vreg)     == 1320, "vreg@1320");
46	
47	// vreg occupies 32 * HYBRID_VLEN_BYTES_MAX bytes; vxsat/vxrm/vcsr follow
48	// it (consuming 24 bytes from the original 256-byte reserved trailer), then
49	// the F13 warmup snapshot pair consumes another 16 bytes; the reserved
50	// trailer keeps the total struct size unchanged.
51	static_assert(offsetof(struct hybrid_state_v1, vxsat)
52	                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX,
53	              "vxsat follows vreg[32 * HYBRID_VLEN_BYTES_MAX]");
54	static_assert(offsetof(struct hybrid_state_v1, vxrm)
55	                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX + 8,
56	              "vxrm follows vxsat");
57	static_assert(offsetof(struct hybrid_state_v1, vcsr)
58	                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX + 16,
59	              "vcsr follows vxrm");
60	static_assert(offsetof(struct hybrid_state_v1, mcycle_at_measure_start)
61	                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX + 24,
62	              "mcycle_at_measure_start follows vcsr (F13)");
63	static_assert(offsetof(struct hybrid_state_v1, minstret_at_measure_start)
64	                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX + 32,
65	              "minstret_at_measure_start follows mcycle_at_measure_start (F13)");
66	static_assert(offsetof(struct hybrid_state_v1, fcsr)
67	                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX + 40,
68	              "fcsr follows the F13 warmup snapshot pair (L20)");
69	static_assert(offsetof(struct hybrid_state_v1, mcache_ctl)
70	                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX + 48,
71	              "mcache_ctl follows fcsr (Andes cache-enable CSR)");
72	static_assert(offsetof(struct hybrid_state_v1, mmisc_ctl)
73	                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX + 56,
74	              "mmisc_ctl follows mcache_ctl");
75	static_assert(offsetof(struct hybrid_state_v1, reserved)
76	                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX + 64,
77	              "reserved follows mmisc_ctl");
78	static_assert(sizeof(struct hybrid_state_v1)
79	                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX + 256,
80	              "hybrid_state_v1 total size unchanged "
81	              "(reserved shrinks 256->192 to absorb vxsat/vxrm/vcsr + warmup "
82	              "pair + fcsr + mcache_ctl/mmisc_ctl)");
83	
84	static_assert(HYBRID_VLEN_BYTES_MAX == 128,
85	              "HYBRID_VLEN_BYTES_MAX covers VLEN up to 1024 bits (L11); "
86	              "changing it shifts every offset after vreg and needs a "
87	              "version bump");
88	static_assert(HYBRID_PMP_CFG_NUM    == 16,  "pmpcfg slot count");
89	static_assert(HYBRID_PMP_ADDR_NUM   == 64,  "pmpaddr entry count");
90	
91	#endif  // HYBRID_STATE_ABI_CHECK_H
92

1	#pragma once
2	
3	#include "hybrid/abstract_command.hpp"
4	#include "hybrid/dmi_poll.hpp"
5	#include "hybrid/program_buffer.hpp"
6	#include "hybrid/state_abi.h"
7	#include "hybrid/v_regfile_xfer.hpp"
8	
9	#include <array>
10	#include <cstdint>
11	#include <optional>
12	#include <stdexcept>
13	#include <string>
