172	TEST_CASE("resume halts the hart before any abstract command")
173	{
174	  RecordingBus bus;
175	  // dmstatus answers halted+resumeack so poll loops finish on the first read.
176	  bus.dmstatus_value = (1u << 9) | (1u << 17);
177	
178	  hybrid::ResumeDriver driver(bus, kScratch);
179	  driver.resume(rv64_state(/*pc=*/0x80001000, /*x10=*/0xdeadbeef));
180	
181	  // The first write must prime dmactive (DM out of reset) BEFORE haltreq is
182	  // accepted; the second write must add haltreq while keeping dmactive set.
183	  REQUIRE(bus.ops.size() >= 2);
184	
185	  const auto& prime = bus.ops[0];
186	  CHECK(prime.kind == DmiOp::Kind::Write);
187	  CHECK(prime.reg == kDmcontrol);
188	  CHECK((prime.value & 1u) == 1u);                  // dmactive
189	  CHECK(((prime.value >> 31) & 1u) == 0u);          // haltreq NOT yet set
190	
191	  const auto& halt = bus.ops[1];
192	  CHECK(halt.kind == DmiOp::Kind::Write);
193	  CHECK(halt.reg == kDmcontrol);
194	  CHECK((halt.value & 1u) == 1u);                   // dmactive still set
195	  CHECK(((halt.value >> 31) & 1u) == 1u);           // haltreq
196	}
