252	  const auto& d0 = bus.ops[cmd_idx - 2];
253	  const auto& d1 = bus.ops[cmd_idx - 1];
254	  CHECK(d0.kind == DmiOp::Kind::Write);
255	  CHECK(d0.reg == kData0);
256	  CHECK(d0.value == uint32_t(pc & 0xffffffffu));
257	  CHECK(d1.kind == DmiOp::Kind::Write);
258	  CHECK(d1.reg == kData1);
259	  CHECK(d1.value == uint32_t((pc >> 32) & 0xffffffffu));
260	}
