347	          "those fields are pass-through-merged at drain time instead")
348	{
349	  RecordingBus bus;
350	  bus.dmstatus_value = (1u << 9) | (1u << 17);
351	
352	  auto s = rv64_state(0x80001000, 0);
353	  s.mstatus = 0x1800ULL;
354	  for (int i = 0; i < HYBRID_PMP_CFG_NUM; ++i)  s.pmpcfg[i]  = 0xa0 + i;
355	  for (int i = 0; i < HYBRID_PMP_ADDR_NUM; ++i) s.pmpaddr[i] = 0xb0 + i;
