357	  hybrid::ResumeDriver driver(bus, kScratch);
358	  driver.resume(s);
359	
360	  const auto ns = cmd_regnos(bus.ops);
361	  // mcycle(0xb00)/minstret(0xb02) are restored by resume (F-T2.4), mscratch
362	  // (0x340) since L23, and mepc(0x341)/mcause(0x342)/mtval(0x343)/mip(0x344)/
363	  // mie(0x304) since L24 -- none of those belong in this "must not program"
364	  // list. It now covers mstatus(0x300, restored only under FP/V; this state
365	  // has neither) plus the S-mode CSRs medeleg(0x302)/mideleg(0x303)/satp(0x180)
366	  // that the M-only default engine does not implement; those stay drain-time
367	  // pass-through.
368	  for (uint16_t csr : {0x300, 0x302, 0x303, 0x180})
369	    CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(csr)));
370	  for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; ++i)
371	    CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(0x3a0 + i)));
