805	TEST_CASE("resume with HYBRID_FLAG_V: PB reload sweeps v0..v31 from scratch "
806	          "before the architectural V-CSR restore and counter restore")
807	{
808	  RecordingBus bus;
809	  bus.dmstatus_value = (1u << 9) | (1u << 17);
810	
811	  auto s = rv64_state(0x80001000, 0);
812	  s.flags  |= HYBRID_FLAG_V;
813	  s.vlenb  = 64;
814	  s.vl     = 16;
815	  s.vtype  = 0xC1;   // differs from the sweep's e8/m1 vtype (0xC0)
816	  s.vstart = 7;
817	
818	  // L26: the scratch GPA is the runtime top-of-mmap value (kScratch), passed
819	  // to the driver -- no longer a fixed constant. Assert the sweep stages it.
820	  hybrid::ResumeDriver driver(bus, kScratch);
821	  driver.resume(s);
822	
823	  // (a) every v0..v31 is reloaded via a vle8.v executed in the Program Buffer.
824	  std::vector<int> missing;
825	  std::optional<std::size_t> first_vle_idx, last_vle_idx;
826	  for (uint16_t v = 0; v < 32; ++v) {
827	    const uint32_t want = hybrid::encode_vle8_v(static_cast<uint8_t>(v), 7);
828	    std::optional<std::size_t> at;
829	    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
830	      const auto& op = bus.ops[i];
831	      if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
832	          && op.value == want) { at = i; break; }
833	    }
834	    if (!at) { missing.push_back(v); continue; }
835	    if (!first_vle_idx || *at < *first_vle_idx) first_vle_idx = at;
836	    if (!last_vle_idx  || *at > *last_vle_idx)  last_vle_idx  = at;
837	  }
838	  CHECK(missing.empty());
839	  REQUIRE(first_vle_idx.has_value());
840	  REQUIRE(last_vle_idx.has_value());
841	
842	  // (b) the per-register scratch GPA is staged in x7 (base pointer) for the
843	  //     first and last register.
844	  auto x7_gpa_staged = [&](uint64_t gpa) {
845	    for (std::size_t i = 2; i < bus.ops.size(); ++i) {
846	      const auto& op = bus.ops[i];
847	      if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
848	          && (op.value & 0xFFFFu) == hybrid::regno_gpr(7)
849	          && ((op.value >> 16) & 1u)) {
850	        const auto& d0 = bus.ops[i - 2];
851	        const auto& d1 = bus.ops[i - 1];
852	        if (d0.reg == kData0 && d0.value == uint32_t(gpa & 0xFFFFFFFFu)
853	            && d1.reg == kData1 && d1.value == uint32_t(gpa >> 32))
854	          return true;
855	      }
856	    }
857	    return false;
858	  };
859	  CHECK(x7_gpa_staged(kScratch));
860	  CHECK(x7_gpa_staged(kScratch + 31ull * HYBRID_VLEN_BYTES_MAX));
861	
862	  // (c)/(d) the sweep runs before the architectural vstart restore (whose
863	  //     vsetvl would otherwise be clobbered) and before the mcycle restore
864	  //     (so the vle8.v insns cannot pollute the resumed counters).
865	  std::optional<std::size_t> vstart_cmd_idx, mcycle_cmd_idx;
866	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
867	    const auto& op = bus.ops[i];
868	    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
869	    const auto regno = static_cast<uint16_t>(op.value & 0xFFFFu);
870	    if (!vstart_cmd_idx && regno == hybrid::regno_csr(0x008)) vstart_cmd_idx = i;
871	    if (!mcycle_cmd_idx && regno == hybrid::regno_csr(0xB00)) mcycle_cmd_idx = i;
872	  }
873	  REQUIRE(vstart_cmd_idx.has_value());
874	  REQUIRE(mcycle_cmd_idx.has_value());
875	  CHECK(*last_vle_idx < *vstart_cmd_idx);
876	  CHECK(*last_vle_idx < *mcycle_cmd_idx);
877	}
