1039	TEST_CASE("L6: S-mode resume writes dcsr.prv = state.priv before resumereq")
1040	{
1041	  RecordingBus bus;
1042	  bus.dmstatus_value = (1u << 9) | (1u << 17);
1043	
1044	  auto s = rv64_state(0x80001000, 0);
1045	  s.priv = 1;  // S-mode at the drain boundary
1046	
1047	  hybrid::ResumeDriver driver(bus, kScratch);
1048	  driver.resume(s);
1049	
1050	  // Exactly one write-COMMAND must target dcsr (0x7B0). The driver
1051	  // read-modify-writes dcsr; the recording bus answers 0 for the read, so
1052	  // the DATA0 staged two ops earlier is exactly the prv field.
1053	  std::vector<std::size_t> idx;
1054	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
1055	    const auto& op = bus.ops[i];
1056	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
1057	        && (op.value & 0xffffu) == kCsrDcsr
1058	        && ((op.value >> 16) & 1u) != 0u) {
1059	      idx.push_back(i);
1060	    }
1061	  }
1062	  REQUIRE(idx.size() == 1);
1063	  REQUIRE(idx[0] >= 2);
1064	  const auto& d0 = bus.ops[idx[0] - 2];
1065	  CHECK(d0.kind == DmiOp::Kind::Write);
1066	  CHECK(d0.reg == kData0);
1067	  CHECK((d0.value & 0x3u) == 1u);
1068	
1069	  // The dcsr write must land before resumereq (bit 30 of dmcontrol).
1070	  std::size_t resume_idx = bus.ops.size();
1071	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
1072	    const auto& op = bus.ops[i];
1073	    if (op.kind == DmiOp::Kind::Write && op.reg == kDmcontrol
1074	        && ((op.value >> 30) & 1u) != 0u) {
1075	      resume_idx = i;
1076	      break;
1077	    }
1078	  }
1079	  CHECK(idx[0] < resume_idx);
1080	}
