1099	TEST_CASE("L6/L2: S/U resume mirrors the producer's PMP block, addr before cfg")
1100	{
1101	  // With PMP implemented and no matching entry, every S/U access faults
1102	  // (priv spec v1.10) -- an S/U ROI cannot even fetch its first insn on the
1103	  // vsim side unless the producer's PMP block is mirrored in.
1104	  RecordingBus bus;
1105	  bus.dmstatus_value = (1u << 9) | (1u << 17);
1106	
1107	  auto s = rv64_state(0x80001000, 0);
1108	  s.priv = 0;  // U-mode
1109	  for (int i = 0; i < HYBRID_PMP_ADDR_NUM; ++i) s.pmpaddr[i] = 0xb000 + i;
1110	  s.pmpcfg[0] = 0x1f;  // entry 0: NAPOT, RWX
1111	
1112	  hybrid::ResumeDriver driver(bus, kScratch);
1113	  driver.resume(s);
1114	
1115	  std::vector<uint16_t> regnos;
1116	  for (const auto& op : bus.ops)
1117	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
1118	        && ((op.value >> 16) & 1u) != 0u)
1119	      regnos.push_back(static_cast<uint16_t>(op.value & 0xffffu));
1120	
1121	  // All 64 pmpaddr CSRs (0x3B0..0x3EF) and the 8 even pmpcfg CSRs
1122	  // (0x3A0,0x3A2,..,0x3AE -- odd ones do not exist on RV64) are written.
1123	  std::size_t first_cfg = regnos.size(), last_addr = 0;
1124	  std::size_t n_addr = 0, n_cfg = 0, n_odd_cfg = 0;
1125	  for (std::size_t i = 0; i < regnos.size(); ++i) {
1126	    const auto r = regnos[i];
1127	    if (r >= 0x3B0 && r <= 0x3EF) { ++n_addr; last_addr = i; }
1128	    if (r >= 0x3A0 && r <= 0x3AF) {
1129	      if ((r & 1u) != 0u) ++n_odd_cfg;
1130	      else { ++n_cfg; if (i < first_cfg) first_cfg = i; }
1131	    }
1132	  }
1133	  CHECK(n_addr == 64u);
1134	  CHECK(n_cfg == 8u);
1135	  CHECK(n_odd_cfg == 0u);
1136	  // cfg activates the entries, so every addr write must precede every cfg
1137	  // write (a cfg-locked entry would discard the addr that follows it).
1138	  CHECK(last_addr < first_cfg);
1139	}
