194	static struct qemu_plugin_register *find_reg(GArray *regs, const char *name)
195	{
196	    for (guint i = 0; i < regs->len; i++) {
197	        qemu_plugin_reg_descriptor *rd =
198	            &g_array_index(regs, qemu_plugin_reg_descriptor, i);
199	        if (g_ascii_strcasecmp(rd->name, name) == 0) {
200	            return rd->handle;
201	        }
202	    }
203	    return NULL;
204	}
