820	QEMU_PLUGIN_EXPORT int qemu_plugin_install(qemu_plugin_id_t id,
821	                                           const qemu_info_t *info,
822	                                           int argc, char **argv)
823	{
824	    (void) info;
825	    for (int i = 0; i < argc; i++) {
826	        g_auto(GStrv) tok = g_strsplit(argv[i], "=", 2);
827	        if (g_strcmp0(tok[0], "outfile") == 0 && tok[1]) {
828	            outfile_path = g_strdup(tok[1]);
829	        } else if (g_strcmp0(tok[0], "enter_pc") == 0 && tok[1]) {
830	            char *endp = NULL;
831	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
832	            if (!endp || *endp != '\0') {
833	                fprintf(stderr, "hybrid_handoff: invalid enter_pc=%s\n",
834	                        tok[1]);
835	                return -1;
836	            }
837	            enter_pc_arg = (uint64_t) v;
838	            pc_mode = 1;
839	        } else if (g_strcmp0(tok[0], "icount") == 0 && tok[1]) {
840	            char *endp = NULL;
841	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
842	            if (!endp || *endp != '\0' || v == 0) {
843	                fprintf(stderr, "hybrid_handoff: invalid icount=%s\n",
844	                        tok[1]);
845	                return -1;
846	            }
847	            icount_target = (uint64_t) v;
848	            icount_mode = 1;
849	        } else if (g_strcmp0(tok[0], "bbv_out") == 0 && tok[1]) {
850	            bbv_out_path = g_strdup(tok[1]);
851	            bbv_mode = 1;
852	        } else if (g_strcmp0(tok[0], "slice") == 0 && tok[1]) {
853	            char *endp = NULL;
854	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
855	            if (!endp || *endp != '\0' || v == 0) {
856	                fprintf(stderr, "hybrid_handoff: invalid slice=%s\n",
857	                        tok[1]);
858	                return -1;
859	            }
860	            bbv_slice_target = (uint64_t) v;
861	        } else if (g_strcmp0(tok[0], "slice_at") == 0 && tok[1]) {
862	            char *endp = NULL;
863	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
864	            if (!endp || *endp != '\0') {
865	                fprintf(stderr, "hybrid_handoff: invalid slice_at=%s\n",
866	                        tok[1]);
867	                return -1;
868	            }
869	            slice_at_target = (uint64_t) v;
870	            slice_consume_mode = 1;
871	        } else if (g_strcmp0(tok[0], "exit_pc") == 0 && tok[1]) {
872	            char *endp = NULL;
873	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
874	            if (!endp || *endp != '\0') {
875	                fprintf(stderr, "hybrid_handoff: invalid exit_pc=%s\n",
876	                        tok[1]);
877	                return -1;
878	            }
879	            exit_pc_arg = (uint64_t) v;
880	            exit_pc_mode = 1;
881	        } else if (g_strcmp0(tok[0], "exit_marker") == 0 && tok[1]) {
882	            char *endp = NULL;
883	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
884	            if (!endp || *endp != '\0') {
885	                fprintf(stderr, "hybrid_handoff: invalid exit_marker=%s\n",
886	                        tok[1]);
887	                return -1;
888	            }
889	            exit_marker_mode = (v != 0);
890	        } else if (g_strcmp0(tok[0], "drain_pc") == 0 && tok[1]) {
891	            char *endp = NULL;
892	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
893	            if (!endp || *endp != '\0') {
894	                fprintf(stderr, "hybrid_handoff: invalid drain_pc=%s\n",
895	                        tok[1]);
896	                return -1;
897	            }
898	            drain_pc_arg = (uint64_t) v;
899	            drain_pc_set = 1;
900	        } else if (g_strcmp0(tok[0], "cosim_pc") == 0 && tok[1]) {
901	            char *endp = NULL;
902	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
903	            if (!endp || *endp != '\0') {
904	                fprintf(stderr, "hybrid_handoff: invalid cosim_pc=%s\n",
905	                        tok[1]);
906	                return -1;
907	            }
908	            cosim_pc_arg = (uint64_t) v;
909	            cosim_pc_mode = 1;
910	        } else if (g_strcmp0(tok[0], "lockstep_pc") == 0 && tok[1]) {
911	            char *endp = NULL;
912	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
913	            if (!endp || *endp != '\0') {
914	                fprintf(stderr, "hybrid_handoff: invalid lockstep_pc=%s\n",
915	                        tok[1]);
916	                return -1;
917	            }
918	            lockstep_pc_arg = (uint64_t) v;
919	            lockstep_pc_mode = 1;
920	        } else if (g_strcmp0(tok[0], "lockstep_max") == 0 && tok[1]) {
921	            char *endp = NULL;
922	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
923	            if (!endp || *endp != '\0') {
924	                fprintf(stderr, "hybrid_handoff: invalid lockstep_max=%s\n",
925	                        tok[1]);
926	                return -1;
927	            }
928	            lockstep_max = (uint64_t) v;
929	        } else if (g_strcmp0(tok[0], "cosim_marker") == 0 && tok[1]) {
930	            char *endp = NULL;
931	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
932	            if (!endp || *endp != '\0') {
933	                fprintf(stderr, "hybrid_handoff: invalid cosim_marker=%s\n",
934	                        tok[1]);
935	                return -1;
936	            }
937	            cosim_marker_mode = (v != 0);
938	        } else if (g_strcmp0(tok[0], "cosim_counts") == 0 && tok[1]) {
939	            g_auto(GStrv) parts = g_strsplit(tok[1], ":", -1);
940	            size_t n = g_strv_length(parts);
941	            if (n == 0) {
942	                fprintf(stderr, "hybrid_handoff: empty cosim_counts\n");
943	                return -1;
944	            }
945	            cosim_counts = g_new0(uint64_t, n);
946	            for (size_t k = 0; k < n; k++) {
947	                char *endp = NULL;
948	                unsigned long long v = g_ascii_strtoull(parts[k], &endp, 0);
949	                if (parts[k][0] == '\0' || !endp || *endp != '\0') {
950	                    fprintf(stderr,
951	                            "hybrid_handoff: invalid cosim_counts entry: %s\n",
952	                            parts[k]);
953	                    return -1;
954	                }
955	                if (k > 0 && v <= cosim_counts[k - 1]) {
956	                    fprintf(stderr, "hybrid_handoff: cosim_counts must be "
957	                                    "strictly ascending\n");
958	                    return -1;
959	                }
960	                cosim_counts[k] = (uint64_t) v;
961	            }
962	            cosim_n_counts = n;
963	        } else if (g_strcmp0(tok[0], "drain_at_exit") == 0 && tok[1]) {
964	            // F14: any non-zero value enables. "1" is the canonical form
965	            // hsim emits; other ints (incl. negatives parsed as huge unsigned)
966	            // also enable -- the flag is a binary switch, not a count.
967	            char *endp = NULL;
968	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
969	            if (!endp || *endp != '\0') {
970	                fprintf(stderr, "hybrid_handoff: invalid drain_at_exit=%s\n",
971	                        tok[1]);
972	                return -1;
973	            }
974	            drain_at_exit_mode = (v != 0);
975	        } else {
976	            fprintf(stderr, "hybrid_handoff: unknown option: %s\n", argv[i]);
977	            return -1;
978	        }
979	    }
980	    if (!outfile_path) {
981	        fputs("hybrid_handoff: outfile=PATH is required\n", stderr);
982	        return -1;
983	    }
984	    if (pc_mode) {
985	        fprintf(stderr,
986	                "hybrid_handoff: PC-mode enter=0x%" PRIx64 "\n",
987	                enter_pc_arg);
988	    }
989	    if (icount_mode) {
990	        fprintf(stderr,
991	                "hybrid_handoff: icount-mode target=%" PRIu64 "\n",
992	                icount_target);
993	    }
994	    if (bbv_mode) {
995	        if (bbv_slice_target == 0) {
996	            fputs("hybrid_handoff: bbv_out= requires slice=N\n", stderr);
997	            return -1;
998	        }
999	        bbv_emit = bbv_emit_new(bbv_out_path, bbv_slice_target);
1000	        if (!bbv_emit) {
1001	            fprintf(stderr, "hybrid_handoff: failed to open bbv_out=%s\n",
1002	                    bbv_out_path);
1003	            return -1;
1004	        }
1005	        fprintf(stderr,
1006	                "hybrid_handoff: bbv-mode out=%s slice=%" PRIu64 "\n",
1007	                bbv_out_path, bbv_slice_target);
1008	    }
1009	    if (slice_consume_mode) {
1010	        if (bbv_slice_target == 0) {
1011	            fputs("hybrid_handoff: slice_at= requires slice=N\n", stderr);
1012	            return -1;
1013	        }
1014	        fprintf(stderr,
1015	                "hybrid_handoff: slice-consume mode slice=%" PRIu64
1016	                " slice_at=%" PRIu64 "\n",
1017	                bbv_slice_target, slice_at_target);
1018	    }
1019	    if (drain_at_exit_mode) {
1020	        fputs("hybrid_handoff: drain-at-exit mode enabled\n", stderr);
1021	        qemu_plugin_register_atexit_cb(id, on_atexit, NULL);
1022	    }
1023	    if (exit_marker_mode || exit_pc_mode) {
1024	        if ((exit_marker_mode && exit_pc_mode) || pc_mode || icount_mode
1025	            || bbv_mode || slice_consume_mode || drain_at_exit_mode
1026	            || cosim_marker_mode || cosim_pc_mode) {
1027	            fputs("hybrid_handoff: oracle exit drain (exit_marker/exit_pc) "
1028	                  "is exclusive with the other trigger modes\n", stderr);
1029	            return -1;
1030	        }
1031	        if (exit_pc_mode) {
1032	            fprintf(stderr,
1033	                    "hybrid_handoff: oracle exit-drain mode exit_pc=0x%"
1034	                    PRIx64 "\n", exit_pc_arg);
1035	        } else {
1036	            fputs("hybrid_handoff: oracle exit-drain mode (exit marker)\n",
1037	                  stderr);
1038	        }
1039	        if (drain_pc_set) {
1040	            fprintf(stderr, "hybrid_handoff: oracle drain_pc=0x%" PRIx64 "\n",
1041	                    drain_pc_arg);
1042	        }
1043	    } else if (drain_pc_set) {
1044	        fputs("hybrid_handoff: drain_pc requires oracle exit-drain mode "
1045	              "(exit_marker/exit_pc)\n", stderr);
1046	        return -1;
1047	    }
1048	    if (cosim_marker_mode || cosim_pc_mode) {
1049	        if ((cosim_marker_mode && cosim_pc_mode) || pc_mode || icount_mode
1050	            || bbv_mode || slice_consume_mode || drain_at_exit_mode) {
1051	            fputs("hybrid_handoff: cosim mode (cosim_marker/cosim_pc) is "
1052	                  "exclusive with the other trigger modes\n", stderr);
1053	            return -1;
1054	        }
1055	        if (cosim_n_counts == 0) {
1056	            fputs("hybrid_handoff: cosim mode requires cosim_counts=a:b:...\n",
1057	                  stderr);
1058	            return -1;
1059	        }
1060	        if (cosim_pc_mode) {
1061	            fprintf(stderr,
1062	                    "hybrid_handoff: cosim mode entry pc=0x%" PRIx64
1063	                    ", %zu drain count(s)\n", cosim_pc_arg, cosim_n_counts);
1064	        } else {
1065	            fprintf(stderr,
1066	                    "hybrid_handoff: cosim mode (entry marker), "
1067	                    "%zu drain count(s)\n", cosim_n_counts);
1068	        }
1069	        // Fresh stream per run: the sink appends, so stale records from a
1070	        // previous run would otherwise survive.
1071	        g_autofree char *stream = g_strdup_printf("%s.ckpts", outfile_path);
1072	        unlink(stream);
1073	    } else if (cosim_n_counts != 0) {
1074	        fputs("hybrid_handoff: cosim_counts requires cosim mode "
1075	              "(cosim_marker/cosim_pc)\n", stderr);
1076	        return -1;
1077	    }
1078	
1079	    if (lockstep_pc_mode) {
1080	        if (pc_mode || icount_mode || bbv_mode || slice_consume_mode
1081	            || drain_at_exit_mode || exit_marker_mode || exit_pc_mode
1082	            || cosim_marker_mode || cosim_pc_mode) {
1083	            fputs("hybrid_handoff: lockstep_pc is exclusive with the other "
1084	                  "trigger modes\n", stderr);
1085	            return -1;
1086	        }
1087	        // outfile IS the record stream in this mode; start it fresh.
1088	        unlink(outfile_path);
1089	        fprintf(stderr,
1090	                "hybrid_handoff: lockstep mode, arm pc=0x%" PRIx64
1091	                ", max records=%" PRIu64 " (0 = until exit), stream=%s\n",
1092	                lockstep_pc_arg, lockstep_max, outfile_path);
1093	    } else if (lockstep_max != 0) {
1094	        fputs("hybrid_handoff: lockstep_max requires lockstep_pc\n", stderr);
1095	        return -1;
1096	    }
1097	
1098	    vcpu_state = qemu_plugin_scoreboard_new(sizeof(VcpuRegs));
1099	    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
1100	    return 0;
1101	}
