12	TEST_CASE("magic and version are stable wire constants")
13	{
14	  CHECK(HYBRID_STATE_MAGIC == 0x42594841u);
15	  // L11 widened vreg to 256 bytes/register, shifting every offset after it;
16	  // version 2 makes readers reject pre-L11 files loudly instead of
17	  // mis-parsing them.
18	  CHECK(HYBRID_STATE_VERSION == 2u);
19	}
20	
21	TEST_CASE("struct is standard-layout, trivially copyable, no tail padding")
22	{
23	  CHECK(std::is_standard_layout_v<hybrid_state_v1>);
24	  CHECK(std::is_trivially_copyable_v<hybrid_state_v1>);
25	  CHECK(sizeof(hybrid_state_v1) % 8 == 0);
26	}
27	
28	TEST_CASE("header field offsets")
29	{
30	  CHECK(offsetof(hybrid_state_v1, magic) == 0);
31	  CHECK(offsetof(hybrid_state_v1, version) == 4);
32	  CHECK(offsetof(hybrid_state_v1, flags) == 8);
33	  CHECK(offsetof(hybrid_state_v1, hart_id) == 12);
34	  CHECK(offsetof(hybrid_state_v1, pc) == 16);
35	  CHECK(offsetof(hybrid_state_v1, priv) == 24);
36	}
37	
38	TEST_CASE("GPR and FPR are 32 * uint64_t each, contiguous")
39	{
40	  hybrid_state_v1 s{};
41	  CHECK(offsetof(hybrid_state_v1, gpr) == 32);
42	  CHECK(sizeof(s.gpr) == 32 * sizeof(uint64_t));
