169	  CHECK(dst.mepc == 0x80002000ULL);
170	  CHECK(dst.mtvec == 0x80000000ULL);
171	  CHECK(dst.satp == 0x8000000000080000ULL);
172	  CHECK(dst.vtype == 0xc0);
173	  CHECK(dst.vl == 4);
174	  CHECK(dst.vlenb == 16);
175	  CHECK(dst.vxsat == 1);
176	  CHECK(dst.vxrm == 2);
177	  CHECK(dst.vcsr == 0x5);
178	  CHECK(std::memcmp(dst.vreg, src.vreg, sizeof(src.vreg)) == 0);
