3	// TLM access helpers for the hybrid shared-memory doctests, over SimpleMemory.
4	// Lightweight temp-file helpers live in test_tmpfile.hpp (no SystemC dep).
5	// Include AFTER `#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN` + <doctest.h>.
6	
7	#include "platform/simple_memory.hpp"
8	#include "test_tmpfile.hpp"
9	
10	#include <doctest.h>
11	#include <systemc>
12	#include <tlm>
13	
14	#include <cstdint>
15	#include <span>
16	
17	namespace hybrid::test {
18	
19	// One blocking TLM access against `mem`, asserting an OK response. `data` is
20	// the write source for TLM_WRITE / the read destination for TLM_READ.
21	template<typename Mem>
22	inline void tlm_access(Mem& mem, tlm::tlm_command cmd, uint64_t addr,
23	                       std::span<uint8_t> data)
24	{
25	  tlm::tlm_generic_payload gp;
26	  gp.set_command(cmd);
27	  gp.set_address(addr);
28	  gp.set_data_ptr(data.data());
29	  gp.set_data_length(data.size());
30	  gp.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
31	  sc_core::sc_time delay = sc_core::SC_ZERO_TIME;
32	  mem.b_transport(gp, delay);
33	  REQUIRE(gp.get_response_status() == tlm::TLM_OK_RESPONSE);
34	}
35	
36	template<typename Mem>
37	inline void tlm_write(Mem& mem, uint64_t addr, std::span<uint8_t> data)
38	{
39	  tlm_access(mem, tlm::TLM_WRITE_COMMAND, addr, data);
40	}
41	
42	template<typename Mem>
43	inline void tlm_read(Mem& mem, uint64_t addr, std::span<uint8_t> out)
44	{
45	  tlm_access(mem, tlm::TLM_READ_COMMAND, addr, out);
46	}
